import{_ as t,c as i,o as a,aj as r}from"./chunks/framework.CDhdelVI.js";const u=JSON.parse('{"title":"Getting Started With KitchenRatio","description":"","frontmatter":{},"headers":[],"relativePath":"guides/getting-started.md","filePath":"guides/getting-started.md"}'),o={name:"guides/getting-started.md"};function s(n,e,l,d,h,c){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="getting-started-with-kitchenratio" tabindex="-1">Getting Started With KitchenRatio <a class="header-anchor" href="#getting-started-with-kitchenratio" aria-label="Permalink to “Getting Started With KitchenRatio”">​</a></h1><p>KitchenRatio helps you build and scale dough formulas quickly using baker’s percentages.<br> If you want the shortest path: pick a preset, set flour, and go to recipe.</p><h2 id="_1-pick-a-preset" tabindex="-1">1. Pick A Preset <a class="header-anchor" href="#_1-pick-a-preset" aria-label="Permalink to “1. Pick A Preset”">​</a></h2><p>Start by choosing a preset (bread, pizza, flatbread, etc.).<br> Presets load proven starting values, and in many cases you can go straight to the recipe from there.</p><p>After selecting a preset, use the <strong>Instructions</strong> button to open a matching recipe guide.</p><h2 id="_2-set-flour-weight" tabindex="-1">2. Set Flour Weight <a class="header-anchor" href="#_2-set-flour-weight" aria-label="Permalink to “2. Set Flour Weight”">​</a></h2><p>Use the <code>+</code> and <code>-</code> buttons to scale your batch size.</p><ul><li>More flour = more dough</li><li>Less flour = less dough</li></ul><p>This can be as small as a single tortilla or large enough for many pizzas.<br> All other ingredient amounts update automatically to keep baker’s percentages consistent.</p><p>You can also open <strong>Flour Options</strong> to create flour blends.</p><h2 id="_3-adjust-main-ratios" tabindex="-1">3. Adjust Main Ratios <a class="header-anchor" href="#_3-adjust-main-ratios" aria-label="Permalink to “3. Adjust Main Ratios”">​</a></h2><p>Tune the core formula:</p><ul><li>Hydration</li><li>Salt</li><li>Yeast</li></ul><p>You can also set water temperature.<br> If you choose <strong>active dry yeast</strong>, extra options appear for bloom liquid source and bloom settings.</p><h2 id="_4-add-ingredients" tabindex="-1">4. Add Ingredients <a class="header-anchor" href="#_4-add-ingredients" aria-label="Permalink to “4. Add Ingredients”">​</a></h2><p>Add ingredients from categories like:</p><ul><li>Fats</li><li>Sugars</li><li>Dairy</li><li>Seeds/Nuts</li><li>Starches</li><li>Misc</li></ul><p>Use these sliders (plus the main sliders above) to fine-tune the dough:</p><ul><li>Increase hydration</li><li>Add a little more egg</li><li>Add ingredients</li><li>Swap/substitute ingredients</li></ul><p>When you choose a preset, the ingredient sliders that appear are pulled from this same ingredient list.</p><h2 id="_5-check-dough-stats" tabindex="-1">5. Check Dough Stats <a class="header-anchor" href="#_5-check-dough-stats" aria-label="Permalink to “5. Check Dough Stats”">​</a></h2><p>The Dough Stats section helps with planning and consistency:</p><ul><li><strong>Total dough estimate</strong> for batch sizing</li><li><strong>Yield Planner</strong> to estimate pieces (like rolls or tortillas)</li><li><strong>Hydration (liquids)</strong> based on added liquids (water, milk, coffee, etc.)</li><li><strong>Effective Hydration</strong> including water contributed by ingredients like eggs, yogurt, and butter</li><li><strong>Absorption estimate</strong> to account for thirstier ingredients (like rye or potato)</li></ul><p>Use this section to build better intuition for dough feel and repeatable results.</p><h2 id="_6-review-recipe" tabindex="-1">6. Review Recipe <a class="header-anchor" href="#_6-review-recipe" aria-label="Permalink to “6. Review Recipe”">​</a></h2><p>The Recipe section reflects your current slider settings.<br> It also correctly accounts for flour/liquid allocated to:</p><ul><li>Preferments</li><li>Scalds</li><li>Yeast bloom liquid</li></ul><p>Use <strong>Share Recipe</strong> to copy a URL with your current settings.<br> You can share that link or paste it somewhere to save your formula.</p><h2 id="_7-optional-support-kitchenratio" tabindex="-1">7. Optional: Support KitchenRatio <a class="header-anchor" href="#_7-optional-support-kitchenratio" aria-label="Permalink to “7. Optional: Support KitchenRatio”">​</a></h2><p>If KitchenRatio helps you, you can leave an optional tip to support updates and hosting.</p><p>Checkout is handled by <strong>Stripe</strong> (third-party payment processor).<br> Payment details are entered there, not stored by KitchenRatio.</p>',31)])])}const g=t(o,[["render",s]]);export{u as __pageData,g as default};
